import{_ as r,a0 as s,w as p,s as u,ao as i,I as o,x as e,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"开源赛车游戏 StuntRally 的新的 2.3 版本看起来棒极了 | LCTT x X-CMD","titleTemplate":false,"description":"开源赛车游戏 StuntRally 的新的 2.3 版本看起来棒极了 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开源赛车游戏 StuntRally 的新的 2.3 版本看起来棒极了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开源赛车游戏 StuntRally 的新的 2.3 版本看起来棒极了 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/The New Open Source StuntRally 2.3 Racing Game Looks Great","title":"开源赛车游戏 StuntRally 的新的 2.3 版本看起来棒极了","tag":"201405","desc":""},"relativePath":"201405/The New Open Source StuntRally 2.3 Racing Game Looks Great.md","filePath":"[post].md"}'),m={name:"201405/The New Open Source StuntRally 2.3 Racing Game Looks Great.md"};function d(S,t,f,T,R,y){const l=s("Link");return p(),u("div",null,[t[16]||(t[16]=i('<h1 id="开源赛车游戏-stuntrally-的新的-2-3-版本看起来棒极了" tabindex="-1">开源赛车游戏 StuntRally 的新的 2.3 版本看起来棒极了 <a class="header-anchor" href="#开源赛车游戏-stuntrally-的新的-2-3-版本看起来棒极了" aria-label="Permalink to “开源赛车游戏 StuntRally 的新的 2.3 版本看起来棒极了”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/The-new-Open-Source-StuntRally-2-3-Racing-Game-Looks-Great-441726-2.jpg" alt=""></p><p>StuntRally是一个有着多达150条特色赛道和大量汽车模型的免费赛车游戏，它刚刚发布了最新的2.3版本，新版本的画质有了很大的提高。</p><p>该游戏是建立在大量的开源技术上的，如Vdrift，bullet，OGRE，PagedGeometry和MyGUI，虽然在此仅仅举了这几个例子，但是这个游戏绝对不是一个简单的项目。 仅仅从他的特点描述中就能看出，StuntRally大概是在Linux平台上最有前景的开源街机赛车游戏之一。</p><p>玩家可以从153条赛车轨道和24个关卡中感受到游戏的魅力，并且这款游戏超过四个小时的游戏时间真是业界良心啊。 StuntRally特色功能有幽灵驾驶模式（在比赛中最接近你的赛车的视角），赛道幽灵车（每条赛道上都有一个绿色的幽灵记录车），当然还有回放（保存你得驾驶记录，并且你可以从其他的摄像头视角观看）。当然，游戏中也有教程，锦标赛，挑战赛以及多人比赛等。但是这些功能都仅仅只是表面的特点。</p><p>如果我们注意到这是一个免费的游戏，仅仅是开发人员在业余时所做的，Stuntrally的图形效果就已经相当不错了。游戏中玩家需要设定八个的图形参数，包裹地形的视差，三维映射，汽车和水中的倒影，水的折射，开花，运动模糊，SSAO，景深，日光和HDR。其中一些最新的功能将需要玩家重新购买一个新的显卡才行。</p><p>除此之外，开发商还开发了赛道编辑器，允许用户实时编辑比赛道路和它们的参数，通过改变赛道的参数、调整地形，甚至修改自己的赛车，从而让驾驶乐趣倍增。</p><p>这次的变更说明显示，所有的赛道都被重新制作了，所有的纹理地形贴图已经升级到1K像素，背景噪音目前也有了很多的变化，不再是单一的一种声音，光线现在也有了多个照射路径，更加真实，草的密度现在已经渲染到了一个极致，动态摄像机也已经添加，并且游戏开始的燃料现在取决于轨道长度。</p><p>此外，用户现在可以选择的地形纹理、草和植被模型窗口，地形编辑，现在按键比之前方便了很多，新版本的编辑器中有大量的修改，比如，图层按钮已被调换，赛道编辑器的起始位置也已经改变，图层，草和植被按钮上的已被更新，对地形和路面参数的表面标签已被添加，等等。</p>',9)),o("p",null,[t[2]||(t[2]=e("关于StuntRally的这一新版本的更多详情，可在",-1)),n(l,{href:"https://code.google.com/p/vdrift-ogre/wiki/VersionHistory"},{default:a(()=>[...t[0]||(t[0]=[e("公告",-1)])]),_:1}),t[3]||(t[3]=e("中找到。你现在可以从官方",-1)),n(l,{href:"http://sourceforge.net/projects/stuntrally/files/"},{default:a(()=>[...t[1]||(t[1]=[e("网站",-1)])]),_:1}),t[4]||(t[4]=e("下载StuntRally2.3。",-1))]),t[17]||(t[17]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),n(l,{href:"http://news.softpedia.com/news/The-new-Open-Source-StuntRally-2-3-Racing-Game-Looks-Great-441726.shtml"},{default:a(()=>[...t[5]||(t[5]=[e("http://news.softpedia.com/news/The-new-Open-Source-StuntRally-2-3-Racing-Game-Looks-Great-441726.shtml",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("译者：",-1)),n(l,{href:"https://github.com/MikeCoder"},{default:a(()=>[...t[7]||(t[7]=[e("MikeCoder",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),n(l,{href:"http://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const L=r(m,[["render",d]]);export{C as __pageData,L as default};
